    12→
    13→export default function ResultsBar({ page, totalProducts, onPageChange }: ResultsBarProps) {
    14→  const [visible, setVisible] = useState(false);
    15→  const perPage = 15;
    16→  const totalPages = Math.ceil(totalProducts / perPage) || 1;
    17→
    18→  useEffect(() => {
    19→    fetch(`${API_URL}/api/results-bar`)
    20→      .then(r => r.json())
    21→      .then(data => setVisible(data.visible));
    22→  }, []);
    23→
    24→  if (!visible || totalProducts === 0) return null;
    25→
    26→  const start = (page - 1) * perPage + 1;
    27→  const end = Math.min(page * perPage, totalProducts);
    28→
    29→  return (
    30→    <div
    31→      data-testid="results-bar"
    32→      className="flex justify-between items-center bg-[var(--card-bg)] py-4 px-5 mb-5 rounded-lg text-sm"
    33→    >
    34→      <span>Showing {start}-{end} of {totalProducts} products</span>
    35→      <div data-testid="pagination" className="flex items-center gap-3">
    36→        <button
    37→          data-testid="prev-page-btn"
    38→          disabled={page === 1}
    39→          onClick={() => onPageChange(page - 1)}
