    48→          onClick={() => onPageChange(page + 1)}
    49→          className="px-4 py-2 rounded cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed hover:not-disabled:opacity-80" style={{ backgroundColor: 'var(--card-bg)', border: '1px solid var(--border-color)' }}
    50→        >
    51→          Next →
    52→        </button>
    53→      </div>
    54→      <span>Sort: Price ▼</span>
    55→    </div>
    56→  );
